s.group             continue         }         if ($line -match '^- `(?<id>TASK-[A-Z0-9-]+)` \\(group ordinal (?<ordinal>\\d+)\\): .* Initial state: (?<state>[^.]+)\\. Depends on: (?<deps>.*)\\.$') {             $depsText = $Matches.deps.Trim()             $deps = if ($depsText -eq 'none') { @() } else { @($depsText -split ',\\s*') }             $current = [ordered]@{                 id = $Matches.id                 group = $groupId                 ordinal = [int]$Matches.ordinal                 state = $Matches.state.Trim()                 dependencies = $deps                 requirements = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)             }             $tasks.Add($current)             continue         }         if ($null -ne $current -and $line -match '^  - (?:FR/AC|TR):') {             foreach ($match in [regex]::Matches($line, '(?:FR|TR|TEST)-[A-Z0-9-]+')) {                 [void]$current.requirements.Add($match.Value)             }         }     }     return @($tasks) }  function Test-TrxEvidence {     <#     .SYNOPSIS     Verifies supplied TRX hashes and summarizes counters without running tests.     #>     param(         [Parameter(Mandatory)][string]$ManifestPath,         [Parameter(Mandatory)][string]$EvidenceDirectory     )      $manifest = Get-Content -Raw -LiteralPath $ManifestPath | ConvertFrom-Json -Depth 100     $entries = if ($manifest.PSObject.Properties['files']) {         @($manifest.PSObject.Properties['files'].Value)     } elseif ($manifest.PSObject.Properties['results']) {         @($manifest.PSObject.Properties['results'].Value)     } elseif ($manifest.PSObject.Properties['entries']) {         @($manifest.PSObject.Properties['entries'].Value)     } else {         @()     }     $checks = [System.Collections.Generic.List[object]]::new()     $totals = [ordered]@{ total = 0; executed = 0; passed = 0; failed = 0; skipped = 0 }     foreach ($entry in $entries) {         $name = if ($entry.PSObject.Properties['path']) {             Split-Path -Leaf ([string]$entry.PSObject.Properties['path'].Value)         } elseif ($entry.PSObject.Properties['file']) {             Split-Path -Leaf ([string]$entry.PSObject.Properties['file'].Value)         } elseif ($entry.PSObject.Properties['name']) {             [string]$entry.PSObject.Properties['name'].Value         } else {             ''         }         if (-not $name.EndsWith('.trx', [System.StringComparison]::OrdinalIgnoreCase)) { continue }         $path = Join-Path $EvidenceDirectory $name         $actualHash = Get-Sha256 -Path $path         $expectedHash = if ($entry.PSObject.Properties['sha256']) {             [string]$entry.PSObject.Properties['sha256'].Value         } elseif ($entry.PSObject.Properties['hash']) {             [string]$entry.PSObject.Properties['hash'].Value         } else {             ''         }         [xml]$trx = Get-Content -Raw -LiteralPath $path         $counters = $trx.TestRun.ResultSummary.Counters         foreach ($key in @('total', 'executed', 'passed', 'failed')) {             if ($counters.PSObject.Properties[$key]) { $totals[$key] += [int]$counters.PSObject.Properties[$key].Value }         }         $notExecuted = if ($counters.PSObject.Properties['notExecuted']) { [int]$counters.PSObject.Properties['notExecuted'].Value } else { 0 }         $totals.skipped += $notExecuted         $checks.Add([ordered]@{             file = $name             expectedSha256 = $expectedHash             actualSha256 = $actualHash             hashMatch = ([string]$expectedHash).ToUpperInvariant() -eq $actualHash             total = [int]$counters.total             executed = [int]$counters.executed             passed = [int]$counters.passed             failed = [int]$counters.failed             skipped = $notExecuted         })     }     return [ordered]@{         manifestSha256 = Get-Sha256 -Path $ManifestPath         trxCount = $checks.Count         hashMatches = @($checks | Where-Object hashMatch).Count         totals = $totals         files = @($checks)     } }  $rootFull = (Resolve-Path -LiteralPath $Root).ProviderPath $planPath = Join-Path $rootFull 'docs/plans/2026-11-10-federation-dolt-bdpv4.md' $beforePlanPath = Join-Path $rootFull 'docs/receipts/federation/20261117-hv-remediation/plan-before-gate-dependencies.md' $payloadPath = Join-Path $rootFull 'docs/receipts/federation/20261117-plan-definitions/plan-requirements-final-v2.json' $gateReceiptPath = Join-Path $rootFull 'docs/receipts/federation/20261117-hv-remediation/gate-dependencies.json' $pdfManifestPath = Join-Path $rootFull 'docs/plans/exports/Federation-2026-11-17-current-complete.manifest.json' $htmlPath = Join-Path $rootFull 'docs/plans/visuals/federation-three-systems.html' $dslPath = Join-Path $rootFull 'docs/plans/federation/workspace.dsl' $unitDirectory = Join-Path $rootFull 'docs/receipts/hv/20261117-federation-plan-unit-evidence' $unitManifestPath = Join-Path $unitDirectory 'manifest.json'  $planLines = Get-Content -LiteralPath $planPath $planText = $planLines -join \"`n\" $section16Offset = $planText.IndexOf('## 16. Canonical requirement definitions', [System.StringComparison]::Ordinal) if ($section16Offset -lt 0) { throw 'Plan section 16 was not found.' } $section16 = $planText.Substring($section16Offset) $payload = Get-Content -Raw -LiteralPath $payloadPath | ConvertFrom-Json -Depth 100  $definitionChecks = [System.Collections.Generic.List[object]]::new() $criterionTotal = 0 foreach ($record in @($payload.records)) {     $heading = \"#### $($record.id): $($record.title)\"     $headingCount = [regex]::Matches($section16, [regex]::Escape($heading)).Count     $descriptionCount = [regex]::Matches($section16, [regex]::Escape([string]$record.description)).Count     $criterionChecks = [System.Collections.Generic.List[object]]::new()     foreach ($criterion in @($record.acceptanceCriteria)) {         $criterionTotal++         $pattern = '(?m)^- \\[(?<mark>[ xX])\\] ' + [regex]::Escape([string]$crite