g.Count -eq 0 -and $extra.Count -eq 0)     }) }  $beforeById = @{} foreach ($task in $beforeTasks) { $beforeById[$task.id] = $task } $newEdges = [System.Collections.Generic.List[string]]::new() foreach ($task in $tasks) {     if (-not $beforeById.ContainsKey($task.id)) { continue }     foreach ($dependency in @($task.dependencies)) {         if ($dependency -notin @($beforeById[$task.id].dependencies)) {             $newEdges.Add(\"$($task.id)->$dependency\")         }     } }  $allTaskIds = @($tasks | ForEach-Object id) $allGroupIds = @($groups | ForEach-Object Name) $unresolvedDependencies = [System.Collections.Generic.List[object]]::new() foreach ($task in $tasks) {     foreach ($dependency in @($task.dependencies)) {         if ($dependency -notin $allTaskIds -and $dependency -notin $allGroupIds) {             $unresolvedDependencies.Add([ordered]@{ task = $task.id; dependency = $dependency })         }     } }  $gateReceipt = Get-Content -Raw -LiteralPath $gateReceiptPath | ConvertFrom-Json -Depth 100 $receiptEdges = @($gateReceipt.changes | ForEach-Object { $gateId = $_.id; @($_.missing | ForEach-Object { \"$gateId->$_\" }) })  $pdfText = Get-Content -Raw -LiteralPath $PdfTextPath $pdfNormalized = ConvertTo-WhitespaceNormalizedText -Text $pdfText $htmlText = Get-Content -Raw -LiteralPath $htmlPath $stateMatches = [regex]::Matches($htmlText, '(?m)^\\s*s\\(''(?<text>.*)''\\s*(?:,\\{.*\\})?\\),?\\s*$') $stateTexts = @($stateMatches | ForEach-Object { $_.Groups['text'].Value }) $stateChecks = @($stateTexts | ForEach-Object {     $normalized = ConvertTo-WhitespaceNormalizedText -Text $_     [ordered]@{ text = $_; printed = $pdfNormalized.Contains($normalized, [System.StringComparison]::Ordinal) } }) $workflowMatches = [regex]::Matches($htmlText, \"\\{name:'(?<name>[^']+)',steps:\\[\") $workflowNames = @($workflowMatches | ForEach-Object { $_.Groups['name'].Value }) $workflowChecks = @($workflowNames | ForEach-Object {     $normalized = ConvertTo-WhitespaceNormalizedText -Text $_     [ordered]@{ name = $_; printed = $pdfNormalized.Contains($normalized, [System.StringComparison]::Ordinal) } })  $dslLines = @(Get-Content -LiteralPath $dslPath | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) $dslLineChecks = [System.Collections.Generic.List[object]]::new() $searchOffset = 0 foreach ($dslLine in $dslLines) {     $needle = ConvertTo-WhitespaceNormalizedText -Text $dslLine     $position = $pdfNormalized.IndexOf($needle, $searchOffset, [System.StringComparison]::Ordinal)     $dslLineChecks.Add([ordered]@{ text = $dslLine; foundInOrder = ($position -ge 0); position = $position })     if ($position -ge 0) { $searchOffset = $position + $needle.Length } }  $pdfManifest = Get-Content -Raw -LiteralPath $pdfManifestPath | ConvertFrom-Json -Depth 100 $attachmentChecks = [System.Collections.Generic.List[object]]::new() foreach ($source in @($pdfManifest.sources)) {     $attachmentPath = Join-Path $AttachmentDirectory ([string]$source.filename)     $actual = if (Test-Path -LiteralPath $attachmentPath) { Get-Sha256 -Path $attachmentPath } else { $null }     $attachmentChecks.Add([ordered]@{         file = [string]$source.filename         exists = Test-Path -LiteralPath $attachmentPath         expectedSha256 = [string]$source.sha256         actualSha256 = $actual         match = ($null -ne $actual -and $actual -eq [string]$source.sha256)     }) } $embeddedManifestPath = Join-Path $AttachmentDirectory 'federation-current-sources.json'  $result = [ordered]@{     generatedAtLocal = (Get-Date).ToString('s')     root = $rootFull     plan = [ordered]@{         sha256 = Get-Sha256 -Path $planPath         lineCount = $planLines.Count         section16Present = $section16Offset -ge 0         section16DefinitionHeadingCount = [regex]::Matches($section16, '(?m)^#### (?:FR|TR|TEST)-').Count     }     canonicalDefinitions = [ordered]@{         payloadSha256 = Get-Sha256 -Path $payloadPath         recordCount = @($payload.records).Count         criterionCountDeclared = [int]$payload.criteriaCount         criterionCountObserved = $criterionTotal         exactDefinitionMatches = @($definitionChecks | Where-Object { $_.headingMatchCount -eq 1 -and $_.descriptionMatchCount -ge 1 -and $_.criterionExactMatches -eq $_.criteria -and $_.satisfactionMatches -eq $_.criteria }).Count         failures = @($definitionChecks | Where-Object { $_.headingMatchCount -ne 1 -or $_.descriptionMatchCount -lt 1 -or $_.criterionExactMatches -ne $_.criteria -or $_.satisfactionMatches -ne $_.criteria })         mappingCount = @($payload.mappings).Count         undefinedImplementationReferences = @($payload.undefinedImplementationReferences)     }     tasks = [ordered]@{         count = $tasks.Count         uniqueIds = @($allTaskIds | Sort-Object -Unique).Count         planningCount = @($tasks | Where-Object state -eq 'Planning').Count         groupCount = $groups.Count         groupOrdinalsContiguous = @($groups | Where-Object {             $ordinals = @($_.Group.ordinal | Sort-Object)             $expectedOrdinals = @(1..$ordinals.Count)             @(Compare-Object -ReferenceObject $expectedOrdinals -DifferenceObject $ordinals).Count -eq 0         }).Count         unresolvedDependencies = @($unresolvedDependencies)         gateCount = $gateChecks.Count         passingGates = @($gateChecks | Where-Object pass).Count         gateChecks = @($gateChecks)         newDirectEdgesFromR1Baseline = $newEdges.Count         receiptDeclaredNewEdges = [int]$gateReceipt.newDirectEdges         receiptEdgeSetMatches = (@(Compare-Object -ReferenceObject @($receiptEdges | Sort-Object) -DifferenceObject @($newEdges | Sort-Object)).Count -eq 0)     }     pdf = [ordered]@{         sha256 = Get-Sha256 -Path (Join-Path $rootFull 'docs/plans/exports/Federation-2026-11-17-current-complete.pdf')         manifestSha256 = Get-Sha256 -Path $pdfManifestPath         extractedTextSha256 = Get-Sha256 -Path $PdfTextPath         workflowCount = $workflowNames.Count      