function Get-TaskCatalog {
    <#
    .SYNOPSIS
    Parses Section 15.4 task identifiers, groups, states, dependencies, and requirement IDs.
    #>
    param(
        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [AllowEmptyString()]
        [string[]]$Lines
    )

    $inCatalog = $false
    $groupId = ''
    $tasks = [System.Collections.Generic.List[object]]::new()
    $current = $null
    foreach ($line in $Lines) {
        if ($line -eq '### 15.4 Groups and Tasks') {
            $inCatalog = $true
            continue
        }
        if ($line -eq '### 15.5 Simulated queue in the current TODO store') { break }
        if (-not $inCatalog) { continue }

        if ($line -match '^#### (?<group>GRP-[A-Z0-9-]+):') {
            $groupId = $Matches.group
            continue
        }
        if ($line -match '^- `(?<id>TASK-[A-Z0-9-]+)` \(group ordinal (?<ordinal>\d+)\): .* Initial state: (?<state>[^.]+)\. Depends on: (?<deps>.*)\.$') {
            $depsText = $Matches.deps.Trim()
            $deps = if ($depsText -eq 'none') { @() } else { @($depsText -split ',\s*') }
            $current = [pscustomobject][ordered]@{
                id = $Matches.id
                group = $groupId
                ordinal = [int]$Matches.ordinal
                state = $Matches.state.Trim()
                dependencies = $deps
                requirements = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
            }
            $tasks.Add($current)
            continue
        }
        if ($null -ne $current -and $line -match '^  - (?:FR/AC|TR):') {
            foreach ($match in [regex]::Matches($line, '(?:FR|TR|TEST)-[A-Z0-9-]+')) {
                [void]$current.requirements.Add($match.Value)
            }
        }
    }
    return @($tasks)
}

